// @ts-nocheck
import './style.css'

type Recipe={name:string;fact:string;difficulty:number;ingredients:string[];customer:string;request:string}
type City={city:string;country:string;x:number;y:number;color:string;recipes:Recipe[];locked?:boolean}
const cities:City[]=[
 {city:'Rome',country:'Italy',x:48,y:36,color:'#ed705f',recipes:[{name:'Cacio e Pepe',fact:'Roman cooks use pasta water to turn pecorino and pepper into a silky sauce.',difficulty:2,ingredients:['Pecorino','Spaghetti','Black pepper'],customer:'Lucia',request:'Extra pepper, please!'},{name:'Supplì',fact:'This crisp Roman rice snack is often called a telephone because melted mozzarella stretches like a cord.',difficulty:3,ingredients:['Rice','Mozzarella','Tomato'],customer:'Marco',request:'Make it extra crispy.'},{name:'Saltimbocca',fact:'Its name means “jumps in the mouth,” a nod to its bright, savory flavor.',difficulty:3,ingredients:['Veal','Prosciutto','Sage'],customer:'Giulia',request:'Lightly seared, please.'}]},
 {city:'Tokyo',country:'Japan',x:82,y:39,color:'#efb94f',recipes:[{name:'Miso Ramen',fact:'Miso ramen became a signature of cold Hokkaido winters in the 1950s.',difficulty:3,ingredients:['Noodles','Miso','Corn'],customer:'Hana',request:'Please keep the egg soft.'},{name:'Onigiri',fact:'These rice triangles have been packed as portable meals in Japan for centuries.',difficulty:2,ingredients:['Rice','Nori','Salmon'],customer:'Ren',request:'Lots of salmon filling.'},{name:'Okonomiyaki',fact:'The name means “grilled as you like it,” making it a famously customizable dish.',difficulty:4,ingredients:['Cabbage','Flour','Pork'],customer:'Yuki',request:'More bonito flakes!'}]},
 {city:'Accra',country:'Ghana',x:45,y:59,color:'#a773e8',recipes:[{name:'Jollof Rice',fact:'Jollof is a beloved West African rice dish with spirited regional variations.',difficulty:3,ingredients:['Rice','Tomato','Scotch bonnet'],customer:'Ama',request:'A little heat is perfect.'},{name:'Kelewele',fact:'Kelewele is ripe plantain seasoned with ginger and pepper, then fried until caramelized.',difficulty:2,ingredients:['Plantain','Ginger','Pepper'],customer:'Kojo',request:'Golden brown, please.'},{name:'Red Red',fact:'This comforting bean stew is often served with fried plantain.',difficulty:4,ingredients:['Black-eyed peas','Tomato','Plantain'],customer:'Efua',request:'Don’t forget the plantain.'}]},
 {city:'Mexico City',country:'Mexico',x:20,y:48,color:'#4fc5a1',recipes:[{name:'Tacos al Pastor',fact:'Al pastor was inspired by Lebanese shawarma traditions brought to Mexico in the early 20th century.',difficulty:3,ingredients:['Pork','Pineapple','Corn tortilla'],customer:'Sofía',request:'Two tacos, plenty of pineapple.'},{name:'Chilaquiles',fact:'Chilaquiles are a clever, delicious way to give yesterday’s tortillas a second life.',difficulty:2,ingredients:['Tortilla chips','Salsa verde','Egg'],customer:'Mateo',request:'Keep the chips a little crunchy.'},{name:'Pozole',fact:'Pozole centers on nixtamalized corn, a food tradition with deep pre-Hispanic roots.',difficulty:4,ingredients:['Hominy','Pork','Radish'],customer:'Elena',request:'Extra radish on top.'}]},
 {city:'Mumbai',country:'India',x:65,y:51,color:'#f48c65',locked:true,recipes:[{name:'Masala Dosa',fact:'Dosa batter is fermented, creating its tangy flavor and crisp texture.',difficulty:4,ingredients:['Rice','Lentils','Potato'],customer:'Anaya',request:'Very crisp, please.'},{name:'Vada Pav',fact:'This potato fritter sandwich is one of Mumbai’s most iconic street foods.',difficulty:3,ingredients:['Potato','Chili','Pav'],customer:'Arjun',request:'Make it spicy.'},{name:'Pav Bhaji',fact:'Pav bhaji began as a quick meal for Mumbai textile mill workers.',difficulty:4,ingredients:['Vegetables','Butter','Pav'],customer:'Priya',request:'Lots of butter.'}]}
]
const savedPreferences=(()=>{try{return JSON.parse(localStorage.getItem('world-chef-preferences')||'{}')}catch{return {}}})()
const state={active:'map',city:cities[0],recipe:cities[0].recipes[0],coins:1240,rep:3,level:2,tutorial:true,station:0,started:0,accuracy:0,heat:55,stirs:0,plate:0,prep:0,dropped:[] as string[],orderReady:false,ambience:['sunlit','sunset','midnight','aurora'].includes(savedPreferences.ambience)?savedPreferences.ambience:'sunlit',cookBackground:typeof savedPreferences.cookBackground==='string'&&/^#[0-9a-f]{6}$/i.test(savedPreferences.cookBackground)?savedPreferences.cookBackground:'#f7f2eb'}
const app=document.querySelector<HTMLDivElement>('#app')!
const recipe=()=>state.recipe
function nav(){return `<nav class="topbar"><a class="brand" data-nav="map"><span>✣</span> WORLD CHEF <i>TYCOON</i></a><div class="navlinks"><button class="${state.active==='map'?'active':''}" data-nav="map">Atlas</button><button class="${state.active==='restaurant'?'active':''}" data-nav="restaurant">Restaurant</button><button class="${state.active==='chef-studio'?'active':''}" data-nav="chef-studio">Chef Studio</button><button class="${state.active==='journal'?'active':''}" data-nav="journal">Food Journal</button></div><div class="wallet"><b>✦ ${state.coins.toLocaleString()}</b><span>● ${state.rep} REP</span></div></nav>`}
function mapView(){return `<section class="view map-view"><div class="map-header"><div><p class="eyebrow">WORLD ATLAS · SELECT A DESTINATION</p><h1>Where will the flavor take you?</h1><p class="lede">Each city has several local dishes, guests, and cooking stories to discover.</p></div><div class="passport"><span>✦</span><b>${state.level}</b><small>CHEF LEVEL</small></div></div><div class="map-card detailed-map"><div class="map-art"><div class="continent americas">NORTH & SOUTH<br>AMERICA</div><div class="continent europe">EUROPE</div><div class="continent africa">AFRICA</div><div class="continent asia">ASIA</div>${cities.map(c=>`<button class="map-dot ${c.locked?'locked':''} ${state.city===c?'current':''}" style="left:${c.x}%;top:${c.y}%;--dot:${c.color}" data-city="${c.city}"><span>${c.city}</span></button>`).join('')}<i class="map-line line-one"></i><i class="map-line line-two"></i></div><aside class="travel-card" id="city-card">${cityCard(state.city)}</aside></div><div class="city-hint"><b>How it works:</b> choose a country, browse its menu, then welcome guests and cook their order at your own pace.</div></section>`}
function cityCard(c:City){return `<span class="pin" style="--dot:${c.color}">● ${c.country.toUpperCase()}</span><h2>${c.city}</h2><p>${c.recipes.length} local dishes are ready to learn.</p><div class="dish-options">${c.recipes.map((r,i)=>`<button class="dish-choice ${state.recipe===r?'selected':''}" data-recipe="${i}"><b>${r.name}</b><small>${r.difficulty} ★ skill</small></button>`).join('')}</div>${c.locked?'<button class="primary disabled">Reach Chef Lv. 4</button>':'<button class="primary" data-action="visit">Visit this city <span>→</span></button>'}`}
function restaurantView(){return `<section class="view restaurant-view"><div class="section-heading"><div><p class="eyebrow">${state.city.city.toUpperCase()} FLAGSHIP · OPEN FOR SERVICE</p><h1>La Tavola <span>✦ Lv. ${state.level}</span></h1><p class="lede">Today’s menu features ${recipe().name}. A guest is walking up to the counter.</p></div></div><div class="restaurant-stage"><div class="sun"></div><div class="window"><i></i><i></i></div><div class="sign">LA TAVOLA</div><div class="shelf">🍅　🧄　🥖</div><div class="plant">♣</div><div class="table"><i></i><i></i><b></b></div><div class="customer"><div class="bubble"><b>${recipe().customer} is ready to order</b><small>Tap them to take the order.</small></div><div class="customer-head"></div><div class="customer-body"></div></div></div><div class="order-ticket"><div class="ticket-avatar">${recipe().customer[0]}</div><div><span>COUNTER GUEST</span><h2>${recipe().customer} wants ${recipe().name}</h2><p>“${recipe().request}”</p></div><button class="primary" data-action="take-order">Take order →</button></div></section>`}
function journalView(){return `<section class="view journal-view"><p class="eyebrow">COLLECTED KNOWLEDGE</p><h1>A journal made by tasting.</h1><div class="journal-grid">${cities.flatMap(c=>c.recipes.slice(0,2).map(r=>`<article style="--accent:${c.color}"><span>${c.country.toUpperCase()}</span><h2>${r.name}</h2><p>${r.fact}</p><footer>${r.difficulty} ★ kitchen skill <b>→</b></footer></article>`)).join('')}</div></section>`}
function orderView(){return `<section class="order-screen"><div class="counter-scene"><p class="eyebrow">ORDER STATION</p><div class="big-guest"><div class="guest-face"></div><div class="guest-shirt"></div></div><div class="speech"><b>Hi Chef! I’d like ${recipe().name}.</b><p>“${recipe().request}”</p><small>Order #${Math.floor(Math.random()*80+20)}</small></div></div><div class="order-summary"><span>NEW ORDER</span><h1>${recipe().name}</h1><p>${recipe().ingredients.join(' · ')}</p><button class="primary" data-action="go-kitchen">Head to kitchen →</button></div></section>`}
function kitchenView(){const r=recipe();const labels=['Ingredient station','Cook station','Finishing station'];return `<section class="kitchen-screen"><header><button class="back" data-action="back-restaurant">← Dining room</button><div><p class="eyebrow">KITCHEN · ${state.tutorial?'TUTORIAL ORDER':'LIVE ORDER'}</p><b>${r.customer}: ${r.name}</b></div><div class="kitchen-time">⏱ <b id="elapsed">${Math.max(0,Math.floor((Date.now()-state.started)/1000))}</b>s</div></header><div class="station-tabs">${labels.map((x,i)=>`<button class="${state.station===i?'active':''}" data-station="${i}"><b>${i+1}</b>${x}</button>`).join('')}</div>${state.tutorial?`<div class="tutorial-tip">✦ Tutorial: finish each station once. Future orders skip these instructions, so you can focus on speed and accuracy.</div>`:''}<main class="station-panel">${station(r)}</main></section>`}
function station(r:Recipe){if(state.station===0)return `<p class="eyebrow">BUILD THE ORDER</p><h1>Choose the right ingredients</h1><p class="station-copy">Select every item on ${r.customer}’s ticket. Wrong choices lower the final rating.</p><div class="ingredient-board">${[...r.ingredients,'Mystery sauce','Banana'].map(x=>`<button class="ingredient ${r.ingredients.includes(x)?'need':''}" data-ingredient="${x}">${x}</button>`).join('')}</div><button class="primary station-next" data-action="next-station">Send to stove →</button>`;if(state.station===1)return `<p class="eyebrow">COOK IT RIGHT</p><h1>Hold the heat in the golden zone</h1><p class="station-copy">Move the dial, then stir the pan in rhythm. Fast hands earn better tips.</p><div class="cook-interactions"><div class="heat-meter"><span style="left:${state.heat}%"></span><i></i></div><input class="heat-slider" type="range" min="0" max="100" value="${state.heat}" data-heat><button class="stir-button" data-action="stir">↻ STIR THE PAN <b>${state.stirs}/5</b></button></div><button class="primary station-next" data-action="next-station">Take it to plating →</button>`;return `<p class="eyebrow">FINISHING STATION</p><h1>Plate with care</h1><p class="station-copy">Add a finishing touch, then send the dish out before your guest loses patience.</p><div class="plate-game"><div class="plate-dish"><span>${state.plate>0?'✦':''}</span></div><div><button class="garnish" data-action="garnish">Add garnish</button><button class="garnish" data-action="garnish">Crack pepper</button><button class="garnish" data-action="garnish">Wipe plate edge</button></div></div><button class="primary station-next" data-action="serve">Serve ${r.customer} →</button>`}
function resultView(){const time=Math.max(1,Math.floor((Date.now()-state.started)/1000));const score=Math.min(100,Math.round(52+state.accuracy*6+state.stirs*5+state.plate*5+Math.max(0,25-time/3)));const stars=score>88?5:score>74?4:score>60?3:2;const tip=50+stars*35;return `<section class="result-screen"><div class="result-card"><p class="eyebrow">ORDER COMPLETE</p><div class="rating-stars">${'★'.repeat(stars)}${'☆'.repeat(5-stars)}</div><h1>${score}% · ${stars} star service</h1><p class="guest-quote">“${score>80?'Exactly what I hoped for — thank you, Chef!':'A good meal — I know you can make it even better next time.'}”<br><b>— ${recipe().customer}</b></p><div class="result-stats"><div><b>${time}s</b><span>TIME</span></div><div><b>+${tip}</b><span>COINS</span></div><div><b>+${stars>3?1:0}</b><span>REP</span></div></div><div class="food-fact"><span>LOCAL FOOD FACT</span><p>${recipe().fact}</p></div><button class="primary" data-action="continue">Welcome next guest →</button></div></section>`}
function render(){const views:{[key:string]:()=>string}={map:mapView,restaurant:restaurantView,'chef-studio':chefStudioView,journal:journalView,order:orderView,kitchen:kitchenView,result:resultView};app.innerHTML=(['map','restaurant','chef-studio','journal'].includes(state.active)?nav():'')+views[state.active]();attach()}
function attach(){
 document.querySelectorAll<HTMLElement>('[data-nav]').forEach(x=>x.onclick=()=>{state.active=x.dataset.nav!;render()})
 document.querySelectorAll<HTMLElement>('[data-city]').forEach(x=>{
  const selectCity=()=>{const c=cities.find(v=>v.city===x.dataset.city)!;if(c.locked){toast('Reach Chef Level 4 to visit this city.');return}state.city=c;state.recipe=c.recipes[0];render()}
  x.onmouseenter=()=>{const c=cities.find(v=>v.city===x.dataset.city)!;const card=document.querySelector('#city-card');if(card)card.innerHTML=cityCard(c)}
  x.onclick=selectCity
 })
 document.querySelectorAll<HTMLElement>('[data-recipe]').forEach(x=>x.onclick=()=>{state.recipe=state.city.recipes[Number(x.dataset.recipe)];render()})
 document.querySelectorAll<HTMLElement>('[data-action]').forEach(x=>x.onclick=()=>act(x.dataset.action!))
 document.querySelectorAll<HTMLInputElement>('[data-heat]').forEach(x=>x.oninput=()=>{state.heat=Number(x.value);render()})
 document.querySelectorAll<HTMLElement>('[data-station]').forEach(x=>x.onclick=()=>{state.station=Number(x.dataset.station);render()})
 document.querySelectorAll<HTMLElement>('[data-ingredient]').forEach(x=>x.onclick=()=>{const correct=recipe().ingredients.includes(x.dataset.ingredient!);state.accuracy+=correct?1:-1;x.classList.toggle('picked');toast(correct?'Correct ingredient!':'That is not on the ticket.')})
 document.querySelectorAll<HTMLElement>('[data-food]').forEach(x=>{x.ondragstart=e=>e.dataTransfer?.setData('food',x.dataset.food||'');x.onclick=()=>dropFood(x.dataset.food||'')})
 document.querySelectorAll<HTMLElement>('[data-dropzone]').forEach(x=>{x.ondragover=e=>e.preventDefault();x.ondrop=e=>{e.preventDefault();dropFood(e.dataTransfer?.getData('food')||'')}})
}
function dropFood(food:string){if(!food||state.dropped.includes(food))return;if(recipe().ingredients.includes(food)){state.dropped.push(food);state.accuracy+=1;toast(`${food} added to the bowl.`)}else{state.accuracy-=1;toast('That ingredient is not on this order.')}render()}
function act(a:string){if(a==='visit'){state.active='restaurant'}if(a==='take-order'){state.active='order'}if(a==='go-kitchen'){state.active='kitchen';state.station=0;state.started=Date.now();state.accuracy=0;state.stirs=0;state.plate=0}if(a==='next-station')state.station=Math.min(2,state.station+1);if(a==='stir'){state.stirs=Math.min(5,state.stirs+1);state.accuracy+=1}if(a==='garnish'){state.plate=Math.min(3,state.plate+1);state.accuracy+=1}if(a==='serve'){state.active='result';state.tutorial=false;state.coins+=225;state.rep+=1}if(a==='continue'||a==='back-restaurant'){state.active='restaurant'}render()}
function toast(message:string){const d=document.createElement('div');d.className='toast';d.textContent=message;document.body.append(d);setTimeout(()=>d.remove(),1800)}

// The kitchen has four hands-on stations; every recipe shares the loop but changes its food, tools, and cooking method.
kitchenView=()=>{const r=recipe();const labels=['Ingredients','Prep','Cook','Finish'];return `<section class="kitchen-screen"><header><button class="back" data-action="back-restaurant">← Dining room</button><div><p class="eyebrow">KITCHEN · ${state.tutorial?'TUTORIAL ORDER':'LIVE ORDER'}</p><b>${r.customer}: ${r.name}</b></div><div class="kitchen-time">⏱ <b>${Math.max(0,Math.floor((Date.now()-state.started)/1000))}</b>s</div></header><div class="station-tabs">${labels.map((x,i)=>`<button class="${state.station===i?'active':''}" data-station="${i}"><b>${i+1}</b>${x}</button>`).join('')}</div>${state.tutorial?'<div class="tutorial-tip">✦ Tutorial: drag ingredients into the bowl, then prepare, cook, and plate the order. Future orders let you play without this guide.</div>':''}<main class="station-panel">${station(r)}</main></section>`}
station=(r:Recipe)=>{const foods:Record<string,string>={Pecorino:'🧀',Spaghetti:'🍝','Black pepper':'🫙',Rice:'🍚',Mozzarella:'🧀',Tomato:'🍅',Veal:'🥩',Prosciutto:'🥓',Sage:'🌿',Noodles:'🍜',Miso:'🥣',Corn:'🌽',Nori:'🍙',Salmon:'🐟',Cabbage:'🥬',Flour:'🌾',Pork:'🥩',Plantain:'🍌',Ginger:'🫚',Pepper:'🌶️','Scotch bonnet':'🌶️','Black-eyed peas':'🫘','Corn tortilla':'🫓',Pineapple:'🍍','Tortilla chips':'🟨','Salsa verde':'🫙',Egg:'🥚',Hominy:'🌽',Radish:'🥗',Potato:'🥔',Chili:'🌶️',Pav:'🥖',Vegetables:'🥕',Butter:'🧈',Lentils:'🫘'};if(state.station===0)return `<p class="eyebrow">INGREDIENT STATION</p><h1>Build ${r.name}</h1><p class="station-copy">Drag the ingredients from your pantry into the mixing bowl.</p><div class="drag-kitchen"><div class="food-shelf">${[...r.ingredients,'Salt','Lemon'].map(x=>`<button draggable="true" class="food-token ${r.ingredients.includes(x)?'needed':''}" data-food="${x}"><i>${foods[x]||'🥣'}</i><span>${x}</span></button>`).join('')}</div><div class="mixing-bowl" data-dropzone><div>${state.dropped.length?state.dropped.map(x=>`<i>${foods[x]||'🥣'}</i>`).join(''):'🥣'}</div><b>${state.dropped.length}/${r.ingredients.length} ingredients</b><small>DROP INGREDIENTS HERE</small></div></div><button class="primary station-next" data-action="next-station">Start prep →</button>`;if(state.station===1)return `<p class="eyebrow">PREP STATION</p><h1>${state.prep<3?'Get your hands to work':'Prep complete!'}</h1><p class="station-copy">${r.name.includes('Ramen')?'Slice, crack, and season your ramen toppings.':r.name.includes('Dosa')?'Mix the batter and spread it thin.':'Chop, crack, and combine everything for the order.'}</p><div class="prep-board"><div class="prep-food">${r.ingredients.slice(0,3).map(x=>`<span>${foods[x]||'🥣'}</span>`).join('')}</div><div class="prep-tools"><button data-action="prep">🔪 Chop <b>${state.prep}/3</b></button><button data-action="prep">🥚 Crack / mix</button><button data-action="prep">💧 Add water</button></div></div><button class="primary station-next" data-action="next-station">Move to ${r.name.includes('Ramen')?'simmer':'cook'} →</button>`;if(state.station===2){const method=r.name.includes('Ramen')||r.name.includes('Pozole')?'SIMMER':r.name.includes('Dosa')||r.name.includes('Tacos')||r.name.includes('Okonomiyaki')?'GRIDDLE':'PAN FRY';const progress=Math.min(100,state.stirs*16+Math.max(0,20-Math.abs(state.heat-55))*2);return `<p class="eyebrow">${method} STATION</p><h1>Watch it cook</h1><p class="station-copy">Keep the heat in the golden zone and stir until the food looks ready.</p><div class="live-cook"><div class="pan ${progress>55?'browning':''}"><div class="food-in-pan">${r.ingredients.slice(0,3).map(x=>foods[x]||'🥣').join('')}</div><i class="steam">♨ ♨</i></div><div class="cook-progress"><i style="width:${progress}%"></i></div><b>${Math.round(progress)}% cooked</b></div><div class="cook-interactions"><input class="heat-slider" type="range" min="0" max="100" value="${state.heat}" data-heat><button class="stir-button" data-action="stir">↻ ${method==='SIMMER'?'STIR POT':'FLIP & STIR'} <b>${state.stirs}/5</b></button></div><button class="primary station-next" data-action="next-station">Take to plating →</button>`}return `<p class="eyebrow">FINISHING STATION</p><h1>Make it beautiful</h1><p class="station-copy">Your completed ${r.name} is on the plate. Add final touches before sending it out.</p><div class="plate-game"><div class="plate-dish completed"><div>${r.ingredients.slice(0,3).map(x=>foods[x]||'🥣').join('')}</div><span>${state.plate>0?'✦':''}</span></div><div><button class="garnish" data-action="garnish">🌿 Add garnish</button><button class="garnish" data-action="garnish">🫙 Final seasoning</button><button class="garnish" data-action="garnish">✨ Clean plate edge</button></div></div><button class="primary station-next" data-action="serve">Serve ${r.customer} →</button>`}
const baseAct=act
// The prep view deliberately mirrors the order on a customer display and the cook's workbench.
// This keeps each action legible to both sides of the counter.
station=(r:Recipe)=>{const foods:Record<string,string>={Pecorino:'🧀',Spaghetti:'🍝','Black pepper':'🫙',Rice:'🍚',Mozzarella:'🧀',Tomato:'🍅',Veal:'🥩',Prosciutto:'🥓',Sage:'🌿',Noodles:'🍜',Miso:'🥣',Corn:'🌽',Nori:'🍙',Salmon:'🐟',Cabbage:'🥬',Flour:'🌾',Pork:'🥩',Plantain:'🍌',Ginger:'🫚',Pepper:'🌶️','Scotch bonnet':'🌶️','Black-eyed peas':'🫘','Corn tortilla':'🫓',Pineapple:'🍍','Tortilla chips':'🟨','Salsa verde':'🫙',Egg:'🥚',Hominy:'🌽',Radish:'🥗',Potato:'🥔',Chili:'🌶️',Pav:'🥖',Vegetables:'🥕',Butter:'🧈',Lentils:'🫘'};const icons=r.ingredients.slice(0,3).map(x=>foods[x]||'🥣').join('');if(state.station===0)return `<p class="eyebrow">INGREDIENT STATION</p><h1>Build ${r.name}</h1><p class="station-copy">Drag the ingredients from your pantry into the mixing bowl.</p><div class="drag-kitchen"><div class="food-shelf">${[...r.ingredients,'Salt','Lemon'].map(x=>`<button draggable="true" class="food-token ${r.ingredients.includes(x)?'needed':''}" data-food="${x}"><i>${foods[x]||'🥣'}</i><span>${x}</span></button>`).join('')}</div><div class="mixing-bowl" data-dropzone><div>${state.dropped.length?state.dropped.map(x=>`<i>${foods[x]||'🥣'}</i>`).join(''):'🥣'}</div><b>${state.dropped.length}/${r.ingredients.length} ingredients</b><small>DROP INGREDIENTS HERE</small></div></div><button class="primary station-next" data-action="next-station">Start prep →</button>`;if(state.station===1){const ingredient=r.ingredients[Math.min(state.prep,2)];return `<p class="eyebrow">PREP MINI-GAME · SLICE TO ORDER</p><h1>${state.prep<3?'Slice the ingredients':'Prep complete!'}</h1><p class="station-copy">Tap the board to slice each ingredient. The customer display updates with every finished cut.</p><div class="prep-dual"><section class="customer-display"><div class="screen-label"><span>● LIVE</span> CUSTOMER DISPLAY</div><div class="display-dish">${icons}</div><h2>${r.name}</h2><p>Fresh prep in progress for ${r.customer}</p><div class="display-steps">${r.ingredients.slice(0,3).map((x,i)=>`<div class="${i<state.prep?'done':''}"><b>${i<state.prep?'✓':i+1}</b>${x}</div>`).join('')}</div><small>${state.prep}/3 ingredients sliced</small></section><section class="chef-screen"><div class="screen-label">CHEF SCREEN · CUTTING BOARD</div><div class="slice-board ${state.prep<3?'slice-ready':'complete'}"><span class="slice-food">${foods[ingredient]||'🥕'}</span><i class="knife">🔪</i><em class="slice-line"></em><div class="sliced-pieces">${Array.from({length:Math.min(4,state.prep+1)},()=>`<b>${foods[ingredient]||'🥕'}</b>`).join('')}</div></div><button class="slice-button" data-action="slice" ${state.prep>=3?'disabled':''}>${state.prep>=3?'✓ ALL SLICED':'🔪 SLICE '+ingredient.toUpperCase()}</button><p class="mini-help">Each click makes one clean cut and updates the screen beside you.</p></section></div><button class="primary station-next" data-action="next-station">Move to cook →</button>`}if(state.station===2){const method=r.name.includes('Ramen')||r.name.includes('Pozole')?'SIMMER':'PAN COOK';const progress=Math.min(100,state.stirs*16+Math.max(0,20-Math.abs(state.heat-55))*2);return `<p class="eyebrow">${method} · STIR MINI-GAME</p><h1>Keep it moving</h1><p class="station-copy">Set the heat in the golden zone, then stir with the wooden spoon until the dish is ready.</p><div class="live-cook"><div class="pan ${progress>55?'browning':''}"><div class="food-in-pan">${icons}</div><i class="steam">♨ ♨</i><i class="wooden-spoon ${state.stirs?'stirring':''}">🥄</i></div><div class="cook-progress"><i style="width:${progress}%"></i></div><b>${Math.round(progress)}% cooked · ${state.stirs}/5 stirs</b></div><div class="cook-interactions"><div class="heat-meter"><span style="left:${state.heat}%"></span><i></i></div><input class="heat-slider" type="range" min="0" max="100" value="${state.heat}" data-heat><button class="stir-button spoon-button" data-action="stir"><span>🥄</span> STIR WITH WOODEN SPOON <b>${state.stirs}/5</b></button></div><button class="primary station-next" data-action="next-station">Take to plating →</button>`}return `<p class="eyebrow">FINISHING STATION</p><h1>Make it beautiful</h1><p class="station-copy">Your completed ${r.name} is on the plate. Add final touches before sending it out.</p><div class="plate-game"><div class="plate-dish completed"><div>${icons}</div><span>${state.plate>0?'✦':''}</span></div><div><button class="garnish" data-action="garnish">🌿 Add garnish</button><button class="garnish" data-action="garnish">🫙 Final seasoning</button><button class="garnish" data-action="garnish">✨ Clean plate edge</button></div></div><button class="primary station-next" data-action="serve">Serve ${r.customer} →</button>`}
act=(a:string)=>{if(a==='visit'){state.active='order';render();return}if(a==='go-kitchen'){state.active='kitchen';state.station=0;state.started=Date.now();state.accuracy=0;state.stirs=0;state.plate=0;state.prep=0;state.dropped=[];render();return}if(a==='next-station'){state.station=Math.min(3,state.station+1);render();return}if(a==='prep'||a==='slice'){if(state.prep<3){state.prep+=1;state.accuracy+=1;toast(state.prep===3?'Prep complete — send it to the pan!':'Clean slice! The customer display is updated.')}render();return}baseAct(a)}
// Keep the chef level visually attached to the Atlas progress indicator.
mapView=()=>{const current=state.level;const xp=(state as any).chefXp||0;const meals=current>=5?2:xp%2;const percent=current>=5?100:meals*50;const milestone=current<3?'Aurora ambience':current<4?'Signature plating':current<5?'Critic\'s Choice':'Every chef perk unlocked';const copy=current>=5?'Master Chef · every milestone complete':`${meals}/2 meals to Lv. ${current+1}`;const panel=`<aside class="atlas-progress" aria-label="Chef level progress"><div class="atlas-progress-top"><span>CHEF LEVEL <strong>LV. ${current}</strong></span><b>${copy}</b></div><div class="atlas-progress-track"><i style="width:${percent}%"></i></div><small>${current>=5?'You have reached the final chef milestone.':`NEXT UNLOCK · ${milestone}`}</small></aside>`;return atlasProgressMapView().replace('</small></div></div><div class="map-card detailed-map">',`</small></div>${panel}</div><div class="map-card detailed-map">`)}
render()
// Combine prep is its own short mini-game, then the same mixture is carried into the pan.
const previousStation=station
const previousAct=act
station=(r:Recipe)=>{const foods:Record<string,string>={Pecorino:'🧀',Spaghetti:'🍝','Black pepper':'🫙',Rice:'🍚',Mozzarella:'🧀',Tomato:'🍅',Veal:'🥩',Prosciutto:'🥓',Sage:'🌿',Noodles:'🍜',Miso:'🥣',Corn:'🌽',Nori:'🍙',Salmon:'🐟',Cabbage:'🥬',Flour:'🌾',Pork:'🥩',Plantain:'🍌',Ginger:'🫚',Pepper:'🌶️','Scotch bonnet':'🌶️','Black-eyed peas':'🫘','Corn tortilla':'🫓',Pineapple:'🍍','Tortilla chips':'🟨','Salsa verde':'🫙',Egg:'🥚',Hominy:'🌽',Radish:'🥗',Potato:'🥔',Chili:'🌶️',Pav:'🥖',Vegetables:'🥕',Butter:'🧈',Lentils:'🫘'};const icons=r.ingredients.slice(0,3).map(x=>foods[x]||'🥣').join('');const mix=state.mix||0;if(state.station===1){if(state.prep<3)return previousStation(r);return `<p class="eyebrow">PREP MINI-GAME · COMBINE</p><h1>Bring it all together</h1><p class="station-copy">Stir the sliced ingredients into one pale mixture before it goes in the pan.</p><div class="combine-game"><section class="customer-display"><div class="screen-label"><span>● LIVE</span> CUSTOMER DISPLAY</div><div class="display-dish">${icons}</div><h2>${r.name}</h2><p>${mix<3?'Chef is combining the fresh ingredients.':'Prep is complete — ready for the heat.'}</p><div class="mix-status"><b>${mix>=3?'✓':'↻'}</b> ${mix}/3 combine turns</div></section><section class="combine-bowl ${mix?'mixing':''} ${mix>=3?'combined':''}"><div class="bowl-rim"><div class="raw-bits">${icons}</div><div class="pale-mixture"></div><i class="mix-spoon">🥄</i></div><button class="slice-button" data-action="combine" ${mix>=3?'disabled':''}>${mix>=3?'✓ MIXTURE READY':'🥄 COMBINE INGREDIENTS'}</button><p class="mini-help">Give the bowl three turns to create your cooking mixture.</p></section></div><button class="primary station-next" data-action="next-station">Move pale mixture to cook →</button>`}if(state.station===2){const heat=Math.max(0,20-Math.abs(state.heat-55))*2;const progress=Math.min(100,state.stirs*16+heat);const cookLevel=Math.min(5,state.stirs);return `<p class="eyebrow">PAN COOK · STIR MINI-GAME</p><h1>Gently cook the mixture</h1><p class="station-copy">The mixture begins pale. Keep it moving with the wooden spoon for a light golden finish.</p><div class="live-cook"><div class="pan cook-level-${cookLevel}"><div class="pale-food"><span></span><span></span><span></span><em>${icons}</em></div><i class="steam">♨ ♨</i><i class="wooden-spoon ${state.stirs?'stirring':''}">🥄</i></div><div class="cook-progress"><i style="width:${progress}%"></i></div><b>${Math.round(progress)}% cooked · ${state.stirs}/5 gentle stirs</b></div><div class="cook-interactions"><div class="heat-meter"><span style="left:${state.heat}%"></span><i></i></div><input class="heat-slider" type="range" min="0" max="100" value="${state.heat}" data-heat><button class="stir-button spoon-button" data-action="stir"><span>🥄</span> STIR WITH WOODEN SPOON <b>${state.stirs}/5</b></button></div><button class="primary station-next" data-action="next-station">Take to plating →</button>`}return previousStation(r)}
act=(a:string)=>{if(a==='go-kitchen')state.mix=0;if(a==='combine'){if((state.mix||0)<3){state.mix=(state.mix||0)+1;state.accuracy+=1;toast(state.mix===3?'Mixture combined — ready for the pan!':'The ingredients are coming together.')}render();return}previousAct(a)}
// The cook and finish views use a composed dish rather than repeating loose ingredient icons.
const prepStation=station
const dishVisual=(r:Recipe,phase:'cook'|'plate')=>{const key=r.name==='Cacio e Pepe'?'cacio':r.name.includes('Ramen')?'ramen':r.name.includes('Tacos')?'tacos':r.name.includes('Rice')||r.name.includes('Jollof')?'rice':'signature';return `<div class="dish-visual ${key} ${phase}"><div class="dish-bowl"><i></i><i></i><i></i><i></i><i></i><b></b></div><span class="dish-sauce"></span><em>${phase==='plate'?'✦':''}</em></div>`}
station=(r:Recipe)=>{if(state.station===2){const heat=Math.max(0,20-Math.abs(state.heat-55))*2;const progress=Math.min(100,state.stirs*16+heat);const cookLevel=Math.min(5,state.stirs);return `<p class="eyebrow">PAN COOK · STIR MINI-GAME</p><h1>Gently cook the mixture</h1><p class="station-copy">The pale ${r.name} mixture is coming together. Stir with the wooden spoon for a light golden finish.</p><div class="live-cook"><div class="pan cook-level-${cookLevel}">${dishVisual(r,'cook')}<i class="steam">♨ ♨</i><i class="wooden-spoon ${state.stirs?'stirring':''}">🥄</i></div><div class="cook-progress"><i style="width:${progress}%"></i></div><b>${Math.round(progress)}% cooked · ${state.stirs}/5 gentle stirs</b></div><div class="cook-interactions"><div class="heat-meter"><span style="left:${state.heat}%"></span><i></i></div><input class="heat-slider" type="range" min="0" max="100" value="${state.heat}" data-heat><button class="stir-button spoon-button" data-action="stir"><span>🥄</span> STIR WITH WOODEN SPOON <b>${state.stirs}/5</b></button></div><button class="primary station-next" data-action="next-station">Take to plating →</button>`}if(state.station===3)return `<p class="eyebrow">FINISHING STATION</p><h1>Make it beautiful</h1><p class="station-copy">Your ${r.name} is plated. Add its final touches before sending it out.</p><div class="plate-game"><div class="plate-dish completed">${dishVisual(r,'plate')}</div><div><button class="garnish" data-action="garnish">🌿 Add garnish</button><button class="garnish" data-action="garnish">🫙 Final seasoning</button><button class="garnish" data-action="garnish">✨ Clean plate edge</button></div></div><button class="primary station-next" data-action="serve">Serve ${r.customer} →</button>`;return prepStation(r)}
// Recipe-specific, flat illustrations keep the food consistent with the rest of the UI.
const illustratedStation=station
const foodIllustration=(r:Recipe,phase:'cook'|'plate')=>{const artwork:Record<string,string>={'Cacio e Pepe':'pasta','Supplì':'suppli','Saltimbocca':'saltimbocca','Miso Ramen':'ramen','Onigiri':'onigiri','Okonomiyaki':'okonomiyaki','Jollof Rice':'jollof','Kelewele':'kelewele','Red Red':'redred','Tacos al Pastor':'tacos','Chilaquiles':'chilaquiles','Pozole':'pozole','Masala Dosa':'dosa','Vada Pav':'vadapav','Pav Bhaji':'pavbhaji'};const kind=artwork[r.name]||'pasta';return `<div class="flat-food ${kind} ${phase}" aria-label="${r.name}"><i></i><i></i><i></i><i></i><b></b></div>`}
station=(r:Recipe)=>{if(state.station===2){const heat=Math.max(0,20-Math.abs(state.heat-55))*2;const progress=Math.min(100,state.stirs*16+heat);const cookLevel=Math.min(5,state.stirs);return `<p class="eyebrow">PAN COOK · STIR MINI-GAME</p><h1>Cook the ${r.name}</h1><p class="station-copy">Keep the heat steady and stir with the wooden spoon until this ${r.name} is ready.</p><div class="live-cook"><div class="pan flat-pan cook-level-${cookLevel}">${foodIllustration(r,'cook')}<i class="steam">♨ ♨</i><i class="wooden-spoon ${state.stirs?'stirring':''}">🥄</i></div><div class="cook-progress"><i style="width:${progress}%"></i></div><b>${Math.round(progress)}% cooked · ${state.stirs}/5 gentle stirs</b></div><div class="cook-interactions"><div class="heat-meter"><span style="left:${state.heat}%"></span><i></i></div><input class="heat-slider" type="range" min="0" max="100" value="${state.heat}" data-heat><button class="stir-button spoon-button" data-action="stir"><span>🥄</span> STIR WITH WOODEN SPOON <b>${state.stirs}/5</b></button></div><button class="primary station-next" data-action="next-station">Take to plating →</button>`}if(state.station===3)return `<p class="eyebrow">FINISHING STATION</p><h1>Make it beautiful</h1><p class="station-copy">Your ${r.name} is plated. Add its final touches before sending it out.</p><div class="plate-game"><div class="plate-dish completed">${foodIllustration(r,'plate')}</div><div><button class="garnish" data-action="garnish">🌿 Add garnish</button><button class="garnish" data-action="garnish">🫙 Final seasoning</button><button class="garnish" data-action="garnish">✨ Clean plate edge</button></div></div><button class="primary station-next" data-action="serve">Serve ${r.customer} →</button>`;return illustratedStation(r)}
// Restaurant décor controls update the dining room in place.
const decor={theme:['sunlit','evening','garden'].includes(savedPreferences.decorTheme)?savedPreferences.decorTheme:'sunlit',table:['oak','teal','berry'].includes(savedPreferences.decorTable)?savedPreferences.decorTable:'oak',chairs:['indigo','terracotta','sage'].includes(savedPreferences.decorChairs)?savedPreferences.decorChairs:'indigo'}
function savePreferences(){try{localStorage.setItem('world-chef-preferences',JSON.stringify({ambience:(state as any).ambience,cookBackground:(state as any).cookBackground,decorTheme:decor.theme,decorTable:decor.table,decorChairs:decor.chairs}))}catch{}}
const decorThemes:Record<string,[string,string,string]>={sunlit:['Sunlit','#efc494','#b97959'],evening:['Evening','#52677a','#38434d'],garden:['Garden','#d2e3c1','#a87855']}
const decorTables:Record<string,string>={oak:'#b7754d',teal:'#4d8581',berry:'#a85b63'}
const decorChairs:Record<string,string>={indigo:'#6975a4',terracotta:'#c66c55',sage:'#71966e'}
restaurantView=()=>{const [themeName,wall,floor]=decorThemes[decor.theme];return `<section class="view restaurant-view"><div class="section-heading"><div><p class="eyebrow">${state.city.city.toUpperCase()} FLAGSHIP · OPEN FOR SERVICE</p><h1>La Tavola <span>✦ Lv. ${state.level}</span></h1><p class="lede">Today’s menu features ${recipe().name}. Make the room feel like your own before service begins.</p></div></div><div class="restaurant-stage" style="--wall:${wall};--floor:${floor};--table:${decorTables[decor.table]};--chairs:${decorChairs[decor.chairs]}"><div class="sun"></div><div class="window"><i></i><i></i></div><div class="sign">LA TAVOLA</div><div class="shelf">🍅　🧄　🥖</div><div class="plant">♣</div><div class="chairs"><i></i><i></i></div><div class="table"><i></i><i></i><b></b></div><div class="customer"><div class="bubble"><b>${recipe().customer} is ready to order</b><small>Tap them to take the order.</small></div><div class="customer-head"></div><div class="customer-body"></div></div></div><div class="order-ticket"><div class="ticket-avatar">${recipe().customer[0]}</div><div><span>COUNTER GUEST</span><h2>${recipe().customer} wants ${recipe().name}</h2><p>“${recipe().request}”</p></div><button class="primary" data-action="take-order">Take order →</button></div><section class="decor-panel"><div><p class="eyebrow">RESTAURANT CUSTOMIZATION</p><h2>Style your dining room</h2><small>Current mood: ${themeName}</small></div><div class="decor-controls"><div class="decor-group"><span>Background</span>${Object.entries(decorThemes).map(([key,[name,color]])=>`<button class="decor-swatch ${decor.theme===key?'selected':''}" style="--swatch:${color}" data-action="decor-theme-${key}" title="${name}"><i></i>${name}</button>`).join('')}</div><div class="decor-group"><span>Tables</span>${Object.entries(decorTables).map(([key,color])=>`<button class="decor-swatch ${decor.table===key?'selected':''}" style="--swatch:${color}" data-action="decor-table-${key}" title="${key} table"><i></i>${key}</button>`).join('')}</div><div class="decor-group"><span>Chairs</span>${Object.entries(decorChairs).map(([key,color])=>`<button class="decor-swatch ${decor.chairs===key?'selected':''}" style="--swatch:${color}" data-action="decor-chairs-${key}" title="${key} chairs"><i></i>${key}</button>`).join('')}</div></div></section></section>`}
const decorAct=act
act=(a:string)=>{if(a.startsWith('decor-')){const [,type,value]=a.split('-');if(type==='theme')decor.theme=value;if(type==='table')decor.table=value;if(type==='chairs')decor.chairs=value;savePreferences();render();return}decorAct(a)}
// Add a kitchen line and a second seating area to make the restaurant feel lived in.
const furnishedRestaurantView=restaurantView
restaurantView=()=>furnishedRestaurantView().replace('<div class="plant">♣</div>','<div class="kitchen-line"><div class="kitchen-tile"></div><div class="kitchen-rail">◉　◉　◉</div><div class="kitchen-pass"><b>ORDER UP</b><i>🍳</i><i>🥘</i></div><div class="kitchen-counter"><span>◒</span><span>◒</span><em>PREP</em></div></div><div class="plant">♣</div>').replace('<div class="customer"><div class="bubble">','<div class="chairs chairs-two"><i></i><i></i></div><div class="table table-two"><i></i><i></i><b></b></div><div class="customer"><div class="bubble">')
const applianceRestaurantView=restaurantView
restaurantView=()=>applianceRestaurantView().replace('<div class="kitchen-tile"></div>','<div class="kitchen-tile"></div><div class="kitchen-fridge"><b></b><i></i></div><div class="kitchen-oven"><b></b><i></i><em></em></div>')
// Chef customization lives alongside the restaurant décor controls.
const chefLook={skin:'warm',hair:'dark',apron:'coral'}
const chefColors={skin:{warm:'#b87958',deep:'#74442f',light:'#edb48e'},hair:{dark:'#342624',brown:'#714634',gold:'#c48c45'},apron:{coral:'#d8675b',blue:'#5e86a5',green:'#5c9273'}}
const chefCharacter=()=>`<div class="restaurant-chef"><div class="chef" style="--skin:${chefColors.skin[chefLook.skin]};--hair:${chefColors.hair[chefLook.hair]};--apron:${chefColors.apron[chefLook.apron]}"><div class="hat"></div><div class="hair"></div><div class="face"><i></i><i></i><b></b></div><div class="neck"></div><div class="body"><span></span></div></div></div>`
function chefStudioView(){const gender=(chefLook as any).gender||'woman';const portrait=chefCharacter().replace('restaurant-chef',`restaurant-chef studio-chef gender-${gender}`);return `<section class="view chef-studio-view"><div class="studio-heading"><div><p class="eyebrow">CHEF STUDIO · PERSONALIZE YOUR LOOK</p><h1>Make the kitchen yours.</h1><p class="lede">Choose the chef who welcomes every guest to La Tavola.</p></div><div class="studio-badge">✦<span>CHEF<br>PROFILE</span></div></div><div class="chef-studio-card"><div class="studio-portrait"><div class="studio-glow"></div>${portrait}<p>${state.city.city} flagship chef</p></div><div class="studio-controls"><p class="eyebrow">APPEARANCE</p><h2>Your chef</h2><p>Mix colors and presentation until the character feels like yours.</p><div class="studio-control"><span>presentation</span><div>${['woman','man','nonbinary'].map(x=>`<button class="gender-choice ${gender===x?'selected':''}" data-action="chef-gender-${x}">${x}</button>`).join('')}</div></div>${(['skin','hair','apron'] as const).map(group=>`<div class="studio-control"><span>${group}</span><div class="studio-swatches">${Object.entries(chefColors[group]).map(([key,color])=>`<button class="chef-swatch ${chefLook[group]===key?'selected':''}" style="--swatch:${color}" data-action="chef-${group}-${key}" title="${key} ${group}"><i></i><em>${key}</em></button>`).join('')}</div></div>`).join('')}<div class="studio-note">Your selection appears in the restaurant and service scenes right away.</div></div></div></section>`}
const chefRestaurantView=restaurantView
restaurantView=()=>chefRestaurantView().replace('<div class="kitchen-line">',`${chefCharacter()}<div class="kitchen-line">`)
const chefAct=act
act=(a:string)=>{if(a.startsWith('chef-')){const [,group,value]=a.split('-');(chefLook as any)[group]=value;render();return}chefAct(a)}
// City dish picker: choose any local dish directly from the city's card.
const originalCityCard=cityCard
cityCard=(c:City)=>`<span class="pin" style="--dot:${c.color}">● ${c.country.toUpperCase()}</span><h2>${c.city}</h2><p>Choose one of ${c.recipes.length} local dishes to cook.</p><div class="dish-options">${c.recipes.map((r,i)=>`<button class="dish-choice ${state.city===c&&state.recipe===r?'selected':''}" data-pick-city="${c.city}" data-pick-recipe="${i}"><b>${state.city===c&&state.recipe===r?'✓ ':''}${r.name}</b><small>${r.difficulty} ★ skill · Select this dish</small></button>`).join('')}</div>${c.locked?'<button class="primary disabled">Reach Chef Lv. 4</button>':'<button class="primary" data-action="visit">Cook selected dish <span>→</span></button>'}`
const attachDishPicker=attach
attach=()=>{attachDishPicker();document.querySelectorAll<HTMLElement>('[data-pick-city]').forEach(x=>x.onclick=()=>{const c=cities.find(v=>v.city===x.dataset.pickCity)!;if(c.locked){toast('Reach Chef Level 4 to visit this city.');return}state.city=c;state.recipe=c.recipes[Number(x.dataset.pickRecipe)];toast(`${state.recipe.name} selected in ${c.city}.`);render()})}
// Finishing touches have their own small animations on the plated dish.
const finishingStation=station
station=(r:Recipe)=>{if(state.station!==3)return finishingStation(r);const finishes=(state as any).finishes||[];return `<p class="eyebrow">FINISHING STATION · FINAL TOUCHES</p><h1>Make it beautiful</h1><p class="station-copy">Give your ${r.name} its final touches, then send it to your guest.</p><div class="plate-game"><div class="plate-dish completed finish-dish ${finishes.join(' ')}">${foodIllustration(r,'plate')}<div class="finish-effects"><i class="leaf leaf-one"></i><i class="leaf leaf-two"></i><i class="salt salt-one"></i><i class="salt salt-two"></i><i class="salt salt-three"></i><i class="plate-shine"></i></div></div><div class="finish-actions"><button class="garnish" data-action="finish-garnish"><span>🌿</span> Add garnish</button><button class="garnish" data-action="finish-season"><span>🧂</span> Final seasoning</button><button class="garnish" data-action="finish-wipe"><span>✨</span> Clean plate edge</button></div></div><button class="primary station-next" data-action="serve">Serve ${r.customer} →</button>`}
const finishingAct=act
act=(a:string)=>{if(a==='go-kitchen')(state as any).finishes=[];if(a.startsWith('finish-')){const effect=a.replace('finish-','');const finishes=(state as any).finishes||[];if(!finishes.includes(effect)){(state as any).finishes=[...finishes,effect];state.plate=Math.min(3,state.plate+1);state.accuracy+=1}toast(effect==='garnish'?'Fresh garnish added!':effect==='season'?'A light pinch of salt finishes the dish.':'Plate edge polished!');render();return}finishingAct(a)}
const delegatedDishAttach=attach
attach=()=>{delegatedDishAttach();app.onclick=(event)=>{const pick=(event.target as HTMLElement).closest<HTMLElement>('[data-pick-city]');if(!pick)return;const c=cities.find(v=>v.city===pick.dataset.pickCity);if(!c||c.locked)return;state.city=c;state.recipe=c.recipes[Number(pick.dataset.pickRecipe)];toast(`${state.recipe.name} selected in ${c.city}.`);render()}}
const fullBodyChefView=restaurantView
restaurantView=()=>fullBodyChefView().replace('class="restaurant-chef"',`class="restaurant-chef gender-${(chefLook as any).gender||'woman'}"`).replace('<div class="chef-options">',`<div class="gender-picker"><span>presentation</span>${['woman','man','nonbinary'].map(x=>`<button class="gender-choice ${((chefLook as any).gender||'woman')===x?'selected':''}" data-action="chef-gender-${x}">${x}</button>`).join('')}</div><div class="chef-options">`)
const selectCityDish=(button:HTMLElement)=>{const c=cities.find(v=>v.city===button.dataset.pickCity);if(!c)return;if(c.locked){toast('Reach Chef Level 4 to visit this city.');return}state.city=c;state.recipe=c.recipes[Number(button.dataset.pickRecipe)];toast(`${state.recipe.name} selected in ${c.city}.`);render()}
const everyCityDishAttach=attach
attach=()=>{everyCityDishAttach();const wireDishButtons=(root:ParentNode)=>root.querySelectorAll<HTMLElement>('[data-pick-city]').forEach(button=>button.onclick=(event)=>{event.stopPropagation();selectCityDish(button)});wireDishButtons(document);document.querySelectorAll<HTMLElement>('[data-city]').forEach(dot=>{dot.onmouseenter=()=>{const c=cities.find(v=>v.city===dot.dataset.city)!;const card=document.querySelector<HTMLElement>('#city-card');if(card){card.innerHTML=cityCard(c);wireDishButtons(card)}}})}

// Let each slice play through before advancing the prep counter, so the food visibly separates on the board.
const animatedSliceStation=station
station=(r:Recipe)=>{const markup=animatedSliceStation(r);if(state.station===3){const last=(state as any).lastFinish||'';return markup.replace('finish-dish ',`finish-dish last-finish-${last} `)}if(state.station===1&&markup.includes('combine-bowl'))return markup.replace('class="combine-bowl','class="combine-bowl manual-mix" data-mix-bowl').replace(/<button class="slice-button" data-action="combine"[\s\S]*?<\/button>/,`<div class="slice-button manual-stir-hint">${(state.mix||0)>=3?'✓ MIXTURE READY':'↻ DRAG THE SPOON AROUND THE BOWL'}</div>`);if(state.station!==1)return markup;const cutting=Boolean((state as any).slicing);const board=markup.replace('slice-board slice-ready',`slice-board ${cutting?'cutting':'slice-ready'}" data-slice-board`);return cutting?board.replace(/<span class="slice-food">([\s\S]*?)<\/span>/,`<div class="cut-food cutting"><span class="food-half food-left">$1</span><span class="food-half food-right">$1</span></div>`):board}
const animatedSliceAct=act
act=(a:string)=>{if(a==='slice'&&state.prep<3){if((state as any).slicing)return;(state as any).slicing=true;render();setTimeout(()=>{(state as any).slicing=false;state.prep+=1;state.accuracy+=1;toast(state.prep===3?'Prep complete — send it to the pan!':'Clean slice! The customer display is updated.');render()},540);return}animatedSliceAct(a)}
const finishAnimationAct=act
act=(a:string)=>{if(a.startsWith('finish-'))(state as any).lastFinish=a.replace('finish-','');finishAnimationAct(a)}

// Mixing responds to a real circular drag around the bowl instead of a button press.
const manualMixAttach=attach
attach=()=>{manualMixAttach();document.querySelectorAll<HTMLElement>('[data-mix-bowl]').forEach(bowl=>{let active=false,lastAngle=0,travel=0;const angle=(event:PointerEvent)=>{const box=bowl.getBoundingClientRect();return Math.atan2(event.clientY-(box.top+box.height/2),event.clientX-(box.left+box.width/2))};const stir=(event:PointerEvent)=>{if(!active||(state.mix||0)>=3)return;const next=angle(event);let delta=next-lastAngle;if(delta>Math.PI)delta-=Math.PI*2;if(delta<-Math.PI)delta+=Math.PI*2;travel+=Math.abs(delta);lastAngle=next;const spoon=bowl.querySelector<HTMLElement>('.mix-spoon');if(spoon)spoon.style.transform=`rotate(${next*180/Math.PI+135}deg)`;bowl.classList.add('mixing');if(travel>=Math.PI*1.45){travel=0;state.mix=(state.mix||0)+1;state.accuracy+=1;toast(state.mix===3?'Mixture combined — ready for the pan!':'Nice stir — keep the spoon moving.');render()}};bowl.onpointerdown=event=>{if((state.mix||0)>=3)return;active=true;lastAngle=angle(event);travel=0;bowl.setPointerCapture(event.pointerId);bowl.classList.add('mixing')};bowl.onpointermove=stir;bowl.onpointerup=()=>{active=false;bowl.classList.remove('mixing')};bowl.onpointercancel=bowl.onpointerup})}

// Kitchen background is a player preference that follows them through every cooking station.
const kitchenBackdrops={cream:'#f7f2eb',mint:'#e5f1eb',sky:'#e6f0f6',lilac:'#eee9f5',peach:'#faeadf'} as const
const themedKitchenView=kitchenView
kitchenView=()=>{const color=(state as any).cookBackground||kitchenBackdrops.cream;const picker=`<div class="kitchen-background-picker"><span>Kitchen color</span>${Object.entries(kitchenBackdrops).map(([name,value])=>`<button class="kitchen-color ${color===value?'selected':''}" style="--kitchen-color:${value}" data-action="cook-bg-${name}" title="${name} kitchen"><i></i></button>`).join('')}<input type="color" value="${color}" data-cook-color aria-label="Choose a custom kitchen color"></div>`;return themedKitchenView().replace('<section class="kitchen-screen">',`<section class="kitchen-screen" style="--kitchen-background:${color}">`).replace('</header>',`</header>${picker}`)}
const kitchenBackgroundAct=act
act=(a:string)=>{if(a.startsWith('cook-bg-')){const key=a.replace('cook-bg-','') as keyof typeof kitchenBackdrops;(state as any).cookBackground=kitchenBackdrops[key];savePreferences();render();return}kitchenBackgroundAct(a)}
const kitchenBackgroundAttach=attach
attach=()=>{kitchenBackgroundAttach();document.querySelectorAll<HTMLInputElement>('[data-cook-color]').forEach(input=>input.oninput=()=>{(state as any).cookBackground=input.value;savePreferences();const screen=document.querySelector<HTMLElement>('.kitchen-screen');if(screen)screen.style.setProperty('--kitchen-background',input.value);document.querySelectorAll('.kitchen-color').forEach(button=>button.classList.remove('selected'))})}

// Service closes with a handoff before the guest shares their rating and a local food fact.
const classicResultView=resultView
resultView=()=>{const time=Math.max(1,Math.floor((Date.now()-state.started)/1000));const score=Math.min(100,Math.round(52+state.accuracy*6+state.stirs*5+state.plate*5+Math.max(0,25-time/3)));const stars=score>88?5:score>74?4:score>60?3:2;const phase=(state as any).resultPhase||'handoff';const guest=recipe().customer;const chef=chefCharacter().replace('restaurant-chef','service-chef');const dish=foodIllustration(recipe(),'plate');if(phase==='handoff')return `<section class="service-screen"><div class="service-card"><p class="eyebrow">ORDER COMPLETE · THE HANDOFF</p><h1>One final touch: serve it with pride.</h1><p class="station-copy">${guest} is waiting for their ${recipe().name}.</p><div class="handoff-scene"><div class="service-chef-wrap">${chef}</div><div class="served-dish">${dish}</div><div class="service-guest"><div class="guest-bubble">That smells wonderful!</div><div class="guest-head"></div><div class="guest-body"></div><b>${guest}</b></div></div><button class="primary" data-action="present-dish">Place the dish on the table →</button></div></section>`;return `<section class="service-screen"><div class="service-card guest-review"><p class="eyebrow">GUEST REVIEW</p><div class="review-scene"><div class="review-guest"><div class="guest-head"></div><div class="guest-body"></div></div><div><div class="rating-stars">${'★'.repeat(stars)}${'☆'.repeat(5-stars)}</div><h1>${score}% · ${stars} star service</h1><p class="guest-quote">“${score>80?'Exactly what I hoped for — thank you, Chef!':'A good meal — I know you can make it even better next time.'}”<br><b>— ${guest}</b></p></div></div><div class="food-fact speech-fact"><span>TRADITIONAL FOOD FACT</span><p>${recipe().fact}</p></div><div class="result-stats"><div><b>${time}s</b><span>TIME</span></div><div><b>+${50+stars*35}</b><span>COINS</span></div><div><b>+${stars>3?1:0}</b><span>REP</span></div></div><button class="primary" data-action="continue">Welcome next guest →</button></div></section>`}
const serviceFlowAct=act
act=(a:string)=>{if(a==='serve')(state as any).resultPhase='handoff';if(a==='present-dish'){(state as any).resultPhase='review';state.active='result';render();return}serviceFlowAct(a)}

const boardSliceAttach=attach
attach=()=>{boardSliceAttach();document.querySelectorAll<HTMLElement>('[data-slice-board]').forEach(board=>board.onclick=()=>{if(state.prep<3)act('slice')})}

// The journal is a cookbook collection: a recipe is revealed only after the player serves it.
const cookbookJournalView=journalView
journalView=()=>{const discovered=(state as any).discovered||[];const all=cities.flatMap(city=>city.recipes.map(recipe=>({city,recipe})));return `<section class="view journal-view cookbook-view"><div class="cookbook-heading"><div><p class="eyebrow">YOUR COOKBOOK · COLLECTION</p><h1>Recipes earned at the table.</h1><p class="lede">Cook dishes for guests to reveal their story and add them to your journal.</p></div><div class="cookbook-count"><b>${discovered.length}</b><span>/ ${all.length} DISCOVERED</span></div></div><div class="cookbook-grid">${all.map(({city,recipe:r})=>{const key=`${city.city}:${r.name}`;const known=discovered.includes(key);return `<article class="cookbook-entry ${known?'discovered':'undiscovered'}" style="--accent:${city.color}"><div class="cookbook-dish">${known?foodIllustration(r,'plate'):'<span>?</span>'}</div><div class="cookbook-copy"><span>${known?city.country.toUpperCase():'UNDISCOVERED RECIPE'}</span><h2>${known?r.name:'Unknown dish'}</h2><p>${known?r.fact:`Cook a dish in ${city.city} to uncover this page.`}</p><footer>${known?`${r.difficulty} ★ kitchen skill`:'✦ Keep cooking to reveal'}</footer></div></article>`}).join('')}</div></section>`}
const cookbookUnlockAct=act
act=(a:string)=>cookbookUnlockAct(a)

// A small daily goal and global ambience controls make each restaurant session feel more alive.
const gameAmbiences={sunlit:'Sunlit',sunset:'Sunset',midnight:'Midnight'} as const
const ambientNav=nav
nav=()=>{const mood=(state as any).ambience||'sunlit';return ambientNav().replace('Food Journal','Cookbook').replace('<div class="wallet">',`<div class="ambience-picker" aria-label="Game ambience"><span>MOOD</span>${Object.entries(gameAmbiences).map(([key,label])=>`<button class="ambience-dot ${mood===key?'selected':''}" data-action="ambience-${key}" title="${label}"><i></i></button>`).join('')}</div><div class="wallet">`)}
const challengeRestaurantView=restaurantView
restaurantView=()=>{const complete=Boolean((state as any).dailyComplete);const challenge=`<section class="daily-challenge ${complete?'complete':''}"><div class="challenge-mark">${complete?'✓':'✦'}</div><div><p class="eyebrow">TODAY'S CHEF CHALLENGE</p><h2>${complete?'Challenge complete!':'Serve one guest with care'}</h2><small>${complete?'You earned a 100-coin service bonus.':'Finish any order today to earn +100 coins.'}</small></div><b>${complete?'BONUS CLAIMED':'+100 COINS'}</b></section>`;return challengeRestaurantView().replace('<section class="chef-customizer"',`${challenge}<section class="chef-customizer"`)}
const livelyGameAct=act
act=(a:string)=>{if(a.startsWith('ambience-')){(state as any).ambience=a.replace('ambience-','');savePreferences();render();return}if(a==='serve'&&!(state as any).dailyComplete){(state as any).dailyComplete=true;state.coins+=100;toast('Daily Chef Challenge complete! +100 coins.')}livelyGameAct(a)}
const ambientRender=render
render=()=>{app.dataset.ambience=(state as any).ambience||'sunlit';ambientRender()}
app.dataset.ambience=(state as any).ambience||'sunlit'

// Pepper is the visible final seasoning, with the same finish action used throughout the cooking flow.
const pepperFinishStation=station
station=(r:Recipe)=>{const markup=pepperFinishStation(r);return state.station===3?markup.replace(/(data-action="finish-season"><span>)[\s\S]*?(<\/span> Final seasoning)/,'$1🌶️$2'):markup}
const pepperToast=toast
toast=(message:string)=>pepperToast(message.replace('A light pinch of salt','Fresh-cracked pepper'))

// Guests now have recognizable roles, visual styling, and a small bit of personality.
const guestProfiles:Record<string,{type:string;label:string;note:string}>={Lucia:{type:'regular',label:'LOCAL REGULAR',note:'Knows the neighborhood favorites by heart.'},Marco:{type:'kid',label:'JUNIOR FOODIE',note:'A curious young eater with big opinions.'},Giulia:{type:'critic',label:'FOOD CRITIC',note:'A sharp palate is taking notes tonight.'},Hana:{type:'foodie',label:'RAMEN ENTHUSIAST',note:'Always looking for the next great bowl.'},Ren:{type:'kid',label:'JUNIOR FOODIE',note:'A curious young eater with big opinions.'},Yuki:{type:'critic',label:'FOOD CRITIC',note:'A sharp palate is taking notes tonight.'},Ama:{type:'regular',label:'LOCAL REGULAR',note:'Knows the neighborhood favorites by heart.'},Kojo:{type:'traveler',label:'TRAVELER',note:'Collecting unforgettable meals around the world.'},Efua:{type:'foodie',label:'HOME COOK',note:'Loves discovering a dish’s hidden details.'},Sofía:{type:'traveler',label:'TRAVELER',note:'Collecting unforgettable meals around the world.'},Mateo:{type:'kid',label:'JUNIOR FOODIE',note:'A curious young eater with big opinions.'},Elena:{type:'critic',label:'FOOD CRITIC',note:'A sharp palate is taking notes tonight.'},Anaya:{type:'foodie',label:'HOME COOK',note:'Loves discovering a dish’s hidden details.'},Arjun:{type:'regular',label:'LOCAL REGULAR',note:'Knows the neighborhood favorites by heart.'},Priya:{type:'traveler',label:'TRAVELER',note:'Collecting unforgettable meals around the world.'}}
const guestStyles:Record<string,{presentation:string;tone:string;outfit:string}>={Lucia:{presentation:'woman',tone:'light',outfit:'coral'},Marco:{presentation:'man',tone:'warm',outfit:'blue'},Giulia:{presentation:'woman',tone:'deep',outfit:'plum'},Hana:{presentation:'woman',tone:'fair',outfit:'sage'},Ren:{presentation:'man',tone:'warm',outfit:'teal'},Yuki:{presentation:'nonbinary',tone:'fair',outfit:'gold'},Ama:{presentation:'woman',tone:'deep',outfit:'berry'},Kojo:{presentation:'man',tone:'deep',outfit:'ochre'},Efua:{presentation:'woman',tone:'deep',outfit:'sage'},Sofía:{presentation:'woman',tone:'warm',outfit:'coral'},Mateo:{presentation:'man',tone:'warm',outfit:'teal'},Elena:{presentation:'woman',tone:'fair',outfit:'plum'},Anaya:{presentation:'woman',tone:'warm',outfit:'gold'},Arjun:{presentation:'man',tone:'deep',outfit:'blue'},Priya:{presentation:'woman',tone:'deep',outfit:'berry'}}
const guestProfile=(customer=recipe().customer)=>({...((guestProfiles[customer])||{type:'regular',label:'LOCAL REGULAR',note:'Ready for a delicious meal.'}),...(guestStyles[customer]||{presentation:'nonbinary',tone:'warm',outfit:'blue'})})
const guestFace=(className:string)=>`<div class="${className}"><i class="guest-hair"></i><i class="guest-ear guest-ear-left"></i><i class="guest-ear guest-ear-right"></i><i class="guest-eyes"><b></b><b></b></i><i class="guest-smile"></i></div>`
const guestBody=(className:string)=>`<div class="${className}"><i class="guest-neck"></i><i class="guest-arm guest-arm-left"></i><i class="guest-arm guest-arm-right"></i><i class="guest-collar"></i><i class="guest-placket"></i><i class="guest-leg guest-leg-left"></i><i class="guest-leg guest-leg-right"></i><i class="guest-shoe guest-shoe-left"></i><i class="guest-shoe guest-shoe-right"></i></div>`
const diverseRestaurantView=restaurantView
restaurantView=()=>{const guest=guestProfile();return diverseRestaurantView().replace('<div class="customer">',`<div class="customer guest ${guest.type} ${guest.presentation} tone-${guest.tone} outfit-${guest.outfit}">`).replace('<div class="bubble"><b>',`<div class="bubble"><span class="guest-role">${guest.label}</span><b>`).replace('Tap them to take the order.',guest.note).replace('<div class="customer-head"></div>',guestFace('customer-head')).replace('<div class="customer-body"></div>',guestBody('customer-body'))}
const diverseOrderView=orderView
orderView=()=>{const guest=guestProfile((state as any).activeGuest||recipe().customer);return diverseOrderView().replace('class="big-guest"',`class="big-guest guest ${guest.type} ${guest.presentation} tone-${guest.tone} outfit-${guest.outfit}"`).replace('<div class="speech"><b>',`<div class="speech"><span class="guest-role">${guest.label}</span><b>`).replace('<div class="guest-face"></div>',guestFace('guest-face')).replace('<div class="guest-shirt"></div>',guestBody('guest-shirt'))}
const diverseResultView=resultView
resultView=()=>{const guest=guestProfile((state as any).activeGuest||recipe().customer);const classes=`guest ${guest.type} ${guest.presentation} tone-${guest.tone} outfit-${guest.outfit}`;return diverseResultView().replace('class="service-guest"',`class="service-guest ${classes}"`).replace('class="review-guest"',`class="review-guest ${classes}"`).replaceAll('<div class="guest-head"></div>',guestFace('guest-head')).replaceAll('<div class="guest-body"></div>',guestBody('guest-body'))}

// Mixing supports both a circular drag and a simple tap, so it stays comfortable on every device.
const flexibleMixStation=station
station=(r:Recipe)=>flexibleMixStation(r).replace(/<div class="slice-button manual-stir-hint">([\s\S]*?)<\/div>/,`<button class="slice-button manual-stir-hint" data-action="combine">$1</button>`).replace('Give the bowl three turns to create your cooking mixture.','Drag the spoon around the bowl, or tap the button to stir once.')

const labeledFinishStation=station
station=(r:Recipe)=>{const markup=labeledFinishStation(r);if(state.station!==3)return markup;const finishes=(state as any).finishes||[];const labels:{[key:string]:string}={garnish:'Fresh herb garnish',season:'Fresh-cracked black pepper',wipe:'Plate edge polished'};const completed=finishes.map((finish:string)=>`<span>✓ ${labels[finish]}</span>`).join('');return markup.replace('<button class="primary station-next" data-action="serve"',`<div class="finish-checklist">${completed||'<span>Choose your finishing touches above.</span>'}</div><button class="primary station-next" data-action="serve"`)}

// Every city is playable immediately; chef levels now reward continued service with useful perks.
cities.forEach(city=>city.locked=false)
;(gameAmbiences as any).aurora='Aurora'
const levelledAmbienceNav=nav
nav=()=>{const output=levelledAmbienceNav();return state.level>=3?output:output.replace(/<button class="ambience-dot[^>]*data-action="ambience-aurora"[\s\S]*?<\/button>/,'')}
const chefProgressRestaurant=restaurantView
restaurantView=()=>{const xp=(state as any).chefXp||0;const current=state.level;const progress=xp%2;const upgrade=current<3?'Unlock Aurora ambience at Lv. 3':current<4?'Unlock Signature Plating at Lv. 4 (+25 coins per order)':current<5?'Unlock Critic’s Choice at Lv. 5 (+1 reputation per order)':'Master Chef perks are active.';const panel=`<section class="chef-progress"><div class="progress-emblem">✦</div><div><p class="eyebrow">CHEF PROGRESSION · LEVEL ${current}</p><h2>${upgrade}</h2><div class="chef-xp"><i style="width:${current>=5?100:progress*50}%"></i></div><small>${current>=5?'MAXIMUM KITCHEN MASTERY':`${progress}/2 meals toward your next level`}</small></div><b>LV. ${current}</b></section>`;return chefProgressRestaurant().replace('<section class="chef-customizer"',`${panel}<section class="chef-customizer"`)}
const unclutteredRestaurantView=restaurantView
restaurantView=()=>{const complete=Boolean((state as any).dailyComplete);const current=state.level;const xp=(state as any).chefXp||0;const progress=xp%2;const upgrade=current<3?'Unlock Aurora ambience at Lv. 3':current<4?'Unlock Signature Plating at Lv. 4 (+25 coins per order)':current<5?'Unlock Critic’s Choice at Lv. 5 (+1 reputation per order)':'Master Chef perks are active.';const challenge=`<section class="daily-challenge ${complete?'complete':''}"><div class="challenge-mark">${complete?'✓':'✦'}</div><div><p class="eyebrow">TODAY'S CHEF CHALLENGE</p><h2>${complete?'Challenge complete!':'Serve one guest with care'}</h2><small>${complete?'You earned a 100-coin service bonus.':'Finish any order today to earn +100 coins.'}</small></div><b>${complete?'BONUS CLAIMED':'+100 COINS'}</b></section>`;const panel=`<section class="chef-progress"><div class="progress-emblem">✦</div><div><p class="eyebrow">CHEF PROGRESSION · LEVEL ${current}</p><h2>${upgrade}</h2><div class="chef-xp"><i style="width:${current>=5?100:progress*50}%"></i></div><small>${current>=5?'MAXIMUM KITCHEN MASTERY':`${progress}/2 meals toward your next level`}</small></div><b>LV. ${current}</b></section>`;return unclutteredRestaurantView().replace('<section class="decor-panel"',`${challenge}${panel}<section class="decor-panel"`)}
const levelProgressAct=act
act=(a:string)=>{if(a==='serve'){const prior=state.level;(state as any).chefXp=((state as any).chefXp||0)+1;state.level=Math.min(5,2+Math.floor((state as any).chefXp/2));if(state.level>=4)state.coins+=25;if(state.level>=5)state.rep+=1;if(state.level>prior)toast(`Chef Level ${state.level} reached — a new upgrade is ready!`)}levelProgressAct(a)}
const atlasProgressMapView=mapView
mapView=()=>{const current=state.level;const xp=(state as any).chefXp||0;const meals=current>=5?2:xp%2;const percent=current>=5?100:meals*50;const milestone=current<3?'Aurora ambience':current<4?'Signature plating':current<5?'Critic’s Choice':'Every chef perk unlocked';const copy=current>=5?'Master Chef · every milestone complete':`${meals}/2 meals to Lv. ${current+1}`;const panel=`<aside class="atlas-progress" aria-label="Chef level progress"><div class="atlas-progress-top"><span>LEVEL PROGRESS</span><b>${copy}</b></div><div class="atlas-progress-track"><i style="width:${percent}%"></i></div><small>${current>=5?'You have reached the final chef milestone.':`NEXT UNLOCK · ${milestone}`}</small></aside>`;return atlasProgressMapView().replace('</small></div></div><div class="map-card detailed-map">',`</small></div>${panel}</div><div class="map-card detailed-map">`)}
const cookbookRewardResultView=resultView
resultView=()=>{const key=`${state.city.city}:${recipe().name}`;const unlocked=((state as any).discovered||[]).includes(key);const reward=`<button class="cookbook-unlock ${unlocked?'unlocked':''}" data-action="unlock-cookbook" ${unlocked?'disabled':''}>${unlocked?'✓ Added to Cookbook':`✦ Unlock ${recipe().name} in Cookbook`}</button>`;return cookbookRewardResultView().replace('<button class="primary" data-action="continue">',`${reward}<button class="primary" data-action="continue">`)}
const cookbookRewardAct=act
act=(a:string)=>{if(a==='unlock-cookbook'){const key=`${state.city.city}:${recipe().name}`;const discovered=(state as any).discovered||[];if(!discovered.includes(key)){(state as any).discovered=[...discovered,key];toast(`${recipe().name} added to your Cookbook!`)}render();return}cookbookRewardAct(a)}
const guestContinuityAct=act
act=(a:string)=>{if(a==='visit'||a==='take-order')(state as any).activeGuest=recipe().customer;guestContinuityAct(a)}
const fourTurnMixStation=station
station=(r:Recipe)=>{const turns=state.mix||0;let markup=fourTurnMixStation(r);if(state.station===1&&markup.includes('combine-bowl')){markup=markup.replaceAll('/3 combine turns','/4 combine turns').replaceAll('three turns','four turns').replace('class="combine-bowl manual-mix" data-mix-bowl','class="combine-bowl"').replace(/class="combine-bowl[^\"]*"/,`class="combine-bowl ${((state as any).mixingPulse)?'stir-pulse':''}`);if(turns===3)markup=markup.replace('✓ MIXTURE READY','↻ STIR 1 MORE TIME').replace(' data-action="combine" disabled',' data-action="combine"').replace('Prep is complete — ready for the heat.','One more stir finishes the mixture.').replace('<b>✓</b>','<b>↻</b>');markup=markup.replace(/<button class="slice-button manual-stir-hint" data-action="combine"[^>]*>[\s\S]*?<\/button>/,`<button class="slice-button manual-stir-hint" data-action="combine" ${turns>=4?'disabled':''}>↻ STIR</button><p class="mix-turns">${turns}/4 combine turns</p>`)}return markup}
const fourTurnMixAct=act
act=(a:string)=>{if(a==='combine'){if((state.mix||0)<4){state.mix=(state.mix||0)+1;state.accuracy+=1;(state as any).mixingPulse=true;toast(state.mix===4?'Mixture combined — ready for the pan!':'Nice stir — keep the spoon moving.');setTimeout(()=>{(state as any).mixingPulse=false;render()},560)}render();return}fourTurnMixAct(a)}
const fourTurnMixAttach=attach
attach=()=>{fourTurnMixAttach();document.querySelectorAll<HTMLElement>('[data-mix-bowl]').forEach(bowl=>{let active=false,lastAngle=0,travel=0;const angle=(event:PointerEvent)=>{const box=bowl.getBoundingClientRect();return Math.atan2(event.clientY-(box.top+box.height/2),event.clientX-(box.left+box.width/2))};const stir=(event:PointerEvent)=>{if(!active||(state.mix||0)>=4)return;const next=angle(event);let delta=next-lastAngle;if(delta>Math.PI)delta-=Math.PI*2;if(delta<-Math.PI)delta+=Math.PI*2;travel+=Math.abs(delta);lastAngle=next;const spoon=bowl.querySelector<HTMLElement>('.mix-spoon');if(spoon)spoon.style.transform=`rotate(${next*180/Math.PI+135}deg)`;bowl.classList.add('mixing');if(travel>=Math.PI*1.45){travel=0;act('combine')}};bowl.onpointerdown=event=>{if((state.mix||0)>=4)return;active=true;lastAngle=angle(event);travel=0;bowl.setPointerCapture(event.pointerId);bowl.classList.add('mixing')};bowl.onpointermove=stir;bowl.onpointerup=()=>{active=false;bowl.classList.remove('mixing')};bowl.onpointercancel=bowl.onpointerup})}
render()
